"""TLV (tag-length-value) codec modeled on DER structure.

Node forms:
    ('prim', tag, payload_bytes)  -- primitive: tag byte without bit 0x20
    ('cons', tag, [children])     -- constructed: tag byte with bit 0x20

Encoding:
    tag      one byte; bit 5 (0x20) set for constructed, low bits = tag number
    length   definite only: short form (<128) or long form via
             0x81 (1 length byte) / 0x82 (2 length bytes)
    value    payload bytes, or concatenated encodings of children
"""

from __future__ import annotations

CONSTRUCTED_FLAG = 0x20


class TLVError(Exception):
    """Base class for all TLV decoding errors."""


class TruncatedError(TLVError):
    pass


class TrailingDataError(TLVError):
    pass


def _encode_length(n: int) -> bytes:
    if n < 0x80:
        return bytes([n])
    if n < 0x100:
        return bytes([0x81, n])
    if n < 0x10000:
        return bytes([0x82, n >> 8, n & 0xFF])
    raise ValueError(f"length {n} too large for definite long form (max 65535)")


def encode(node) -> bytes:
    kind, tag, value = node
    if not isinstance(tag, int) or not (0 <= tag <= 0x1F):
        raise ValueError(f"tag must be an integer in [0, 31], got {tag!r}")
    if kind == "prim":
        payload = value
        if not isinstance(payload, (bytes, bytearray)):
            raise TypeError("primitive payload must be bytes")
        head = bytes([tag])
    elif kind == "cons":
        children = value
        body = b"".join(encode(child) for child in children)
        head = bytes([tag | CONSTRUCTED_FLAG])
        payload = body
    else:
        raise ValueError(f"unknown node kind {kind!r}; expected 'prim' or 'cons'")
    return head + _encode_length(len(payload)) + payload


def decode(data: bytes, offset: int = 0) -> tuple[dict, int]:
    """Decode one TLV starting at *offset*; return (node, end_offset)."""
    data = bytes(data)

    def fail(msg):
        return TLVError(f"{msg} at byte offset {offset}")

    if offset >= len(data):
        raise TruncatedError(
            f"truncated: missing tag byte at byte offset {offset}"
        )
    tag_byte = data[offset]
    constructed = bool(tag_byte & CONSTRUCTED_FLAG)
    tag = tag_byte & ~CONSTRUCTED_FLAG
    pos = offset + 1

    if pos >= len(data):
        raise TruncatedError(
            f"truncated: missing length byte after tag at byte offset {pos}"
        )
    first = data[pos]
    pos += 1
    if first < 0x80:
        length = first
    elif first == 0x81:
        if pos >= len(data):
            raise TruncatedError(
                "truncated: 0x81 long-form length missing its length byte "
                f"at byte offset {pos}"
            )
        length = data[pos]
        pos += 1
        if length < 0x80:
            raise TLVError(
                f"non-minimal long-form length 0x81 used for short-form value "
                f"{length} at byte offset {offset}"
            )
    elif first == 0x82:
        if pos + 1 >= len(data):
            raise TruncatedError(
                "truncated: 0x82 long-form length missing length bytes "
                f"at byte offset {pos}"
            )
        length = (data[pos] << 8) | data[pos + 1]
        pos += 2
        if length < 0x100:
            raise TLVError(
                f"non-minimal long-form length 0x82 used for shorter encoding "
                f"at byte offset {offset}"
            )
    else:
        raise TLVError(
            f"unsupported long-form length prefix 0x{first:02x} "
            f"(only 0x81/0x82 supported) at byte offset {offset}"
        )

    end = pos + length
    if end > len(data):
        raise TruncatedError(
            f"truncated value: declared length {length} exceeds available "
            f"{len(data) - pos} bytes, ends at byte offset {end}"
        )

    if constructed:
        children = []
        child_pos = pos
        while child_pos < end:
            try:
                child, child_pos = decode(data, child_pos)
            except TLVError as exc:
                raise type(exc)(
                    str(exc)
                    + f" (child of TLV with tag {tag} spanning offsets "
                    f"{offset}..{end})"
                ) from None
            if child_pos > end:
                raise TLVError(
                    f"child overruns its parent: parent (tag {tag}) ends at "
                    f"byte offset {end} but child extends past it"
                )
            children.append(child)
        if child_pos != end:
            raise TLVError(
                f"child overruns its parent: last child of parent (tag {tag}) "
                f"starting at byte offset {offset} crosses the parent boundary "
                f"at byte offset {end}"
            )
        return {"kind": "cons", "tag": tag, "children": children}, end

    return {"kind": "prim", "tag": tag, "payload": data[pos:end]}, end


def decode_all(data: bytes) -> dict:
    """Decode exactly one top-level TLV occupying the entire input."""
    node, end = decode(data)
