    if kind == "prim":
        return ("prim", tag, bytes(value))
    return ("cons", tag, [_norm(c) for c in value])


def round_trip(node) -> None:
    decoded = decode_all(encode(_norm(node)))
    assert (
        decoded["tag"] == _norm(node)[1]
        and decoded["kind"] == _norm(node)[0]
    )

